	protected static bool contextHasMatchingBreakpoints(ActionContext context,
			Predicate<LogicalBreakpointRow> logicalCase,
			Predicate<BreakpointLocationRow> locationCase) {
		if (context == null) {
			return false;
		}
		if (context is DebuggerLogicalBreakpointsActionContext) {
			DebuggerLogicalBreakpointsActionContext ctx =
				(DebuggerLogicalBreakpointsActionContext) context;
			return ctx.getSelection().stream().anyMatch(logicalCase);
		}
		if (context is DebuggerBreakpointLocationsActionContext) {
			DebuggerBreakpointLocationsActionContext ctx =
				(DebuggerBreakpointLocationsActionContext) context;
			return ctx.getSelection().stream().anyMatch(locationCase);
		}
		return false;
	}

