	protected abstract class CommonMakeBreakpointsEffectiveAction : AbstractMakeBreakpointsEffectiveAction {
		public static readonly string GROUP = DebuggerResources.GROUP_BREAKPOINTS;

		public CommonMakeBreakpointsEffectiveAction() : base(plugin)
    {
			setToolBarData(new ToolBarData(ICON, GROUP));
		}

		/* @Override */
		public void actionPerformed(ActionContext context) {
			Set<LogicalBreakpoint> enablable = breakpointService.getAllBreakpoints()
					.stream()
					.filter(lb => lb.computeState() == State.INEFFECTIVE_ENABLED &&
						!lb.getMappedTraces().isEmpty())
					.collect(Collectors.toSet());
			breakpointService.enableAll(enablable, null).exceptionally(ex => {
				breakpointError("Make Breakpoints Effective", "Could not enable breakpoints", ex);
				return null;
			});
		}
	}

	protected class MakeBreakpointsEffectiveAction : CommonMakeBreakpointsEffectiveAction {
		public MakeBreakpointsEffectiveAction() : base()
    {
			addLocalAction(this);
			setEnabled(false);
		}

		/* @Override */
		public bool isEnabledForContext(ActionContext context) {
			if (breakpointService == null) {
				return false;
			}
			Set<LogicalBreakpoint> all = breakpointService.getAllBreakpoints();
			foreach (LogicalBreakpoint lb in all) {
				if (lb.computeState() != State.INEFFECTIVE_ENABLED) {
					continue;
				}
				if (lb.getMappedTraces().isEmpty()) {
					continue;
				}
				return true;
			}
			return false;
		}
	}

