	class LocationsBySelectedBreakpointsTableFilter : TableFilter<BreakpointLocationRow> {
		/* @Override */
		public bool acceptsRow(BreakpointLocationRow locationRow) {
			if (isFilterByCurrentTrace() &&
				locationRow.getTraceBreakpoint().getTrace() != currentTrace) {
				return false;
			}
			if (isFilterLocationsByBreakpoints()) {
				List<LogicalBreakpointRow> selBreakRows = breakpointFilterPanel.getSelectedItems();
				if (selBreakRows == null || selBreakRows.isEmpty()) {
					return true;
				}
				foreach (LogicalBreakpointRow breakRow in selBreakRows) {
					if (breakRow.getLogicalBreakpoint()
							.getTraceBreakpoints()
							.contains(locationRow.getTraceBreakpoint())) {
						return true;
					}
				}
				return false;
			}
			return true;
		}

		/* @Override */
		public bool isSubFilterOf(TableFilter<object> tableFilter) {
			return false;
		}
	}

	protected class ForBreakpointLocationsTraceListener : TraceDomainObjectListener {
		private Trace trace;

		public ForBreakpointLocationsTraceListener(Trace trace) {
			this.trace = trace;
			listenForUntyped(DomainObjectEvent.RESTORED, e => objectRestored());
			listenFor(TraceEvents.BREAKPOINT_ADDED, this.locationAdded);
			listenFor(TraceEvents.BREAKPOINT_CHANGED, this.locationChanged);
			listenFor(TraceEvents.BREAKPOINT_LIFESPAN_CHANGED, this.locationLifespanChanged);
			listenFor(TraceEvents.BREAKPOINT_DELETED, this.locationDeleted);

			trace.addListener(this);
		}

		private void objectRestored() {
			reloadBreakpointLocations(trace);
		}

		private bool isVisible(TraceBreakpointLocation location) {
			long snap = traceManager.getCurrentFor(trace).getSnap();
			return location.isValid(snap);
		}

		private void locationAdded(TraceBreakpointLocation location) {
			if (!isVisible(location)) {
				return;
			}
			breakpointLocationAdded(location);
		}

		private void locationChanged(TraceBreakpointLocation location) {
			if (!isVisible(location)) {
				return;
			}
			breakpointLocationUpdated(location);
		}

		private void locationLifespanChanged(TraceBreakpointLocation location, Lifespan oldSpan,
				Lifespan newSpan) {
			long snap = traceManager.getCurrentFor(trace).getSnap();
			bool isLiveOld = oldSpan.contains(snap);
			bool isLiveNew = newSpan.contains(snap);
			if (isLiveOld == isLiveNew) {
				return;
			}
			if (isLiveOld) {
				breakpointLocationRemoved(location);
			}
			else {
				breakpointLocationAdded(location);
			}
		}

		private void locationDeleted(TraceBreakpointLocation location) {
			breakpointLocationRemoved(location);
		}

		private void dispose() {
			trace.removeListener(this);
		}
	}

